+    static gtsam::Vector evaluateError_(const NavState &x1, const NavState &x2, double dt) {
+        const Velocity3 &v1 = x1.v();
+        const Velocity3 &v2 = x2.v();
+        const Point3 &p1 = x1.t();
+        const Point3 &p2 = x2.t();
+
