+           << " Coefficient: " << coefficient1 << endl;
+      cout << "                      "
+           << "Row: " << row2_ << " Coefficient: " << coefficient2 << endl;
+    }
+  }
+
+  void addRow(
+      boost::fusion::vector<Chars, char, Chars, Chars, Chars> const &vars) {
+    string name_ = fromChars<3>(vars);
