+
+    for (auto kv : IG) {
+      map<Key, Matrix11> keyMatrixMapNeg;
+      map<Key, Matrix11> keyMatrixMapPos;
+      for (auto km : kv.second) {
+        keyMatrixMapPos.insert(km);
