+/*
+ * ImuFactor.h
+ *
+ *  Created on: Jun 29, 2014
+ *      Author: krunal
+ */
+
+#pragma once
+
+#include <gtsam/nonlinear/NonlinearFactor.h>
+#include <gtsam/linear/GaussianFactor.h>
+#include <gtsam/navigation/ImuBias.h>
