+    std::set<Key> keys2 = expressionA2_->keys();
+    std::set<Key> keys3 = expressionA3_->keys();
+    keys2.insert(keys3.begin(), keys3.end());
+    keys1.insert(keys2.begin(), keys2.end());
+    return keys1;
+  }
+
