+  /* ************************************************************************* */
+  Vector Vector_(size_t m, ...) {
+    Vector v(m);
+    va_list ap;
+    va_start(ap, m);
+    for( size_t i = 0 ; i < m ; i++) {
+      double value = va_arg(ap, double);
+      v(i) = value;
+    }
+    va_end(ap);
+    return v;
