+    boost::variate_generator<boost::minstd_rand&, boost::normal_distribution<double> > norm(generator, norm_dist);
+    
+    Vector v(dim);
+    Vector::iterator it_v;
+    for(it_v=v.begin(); it_v!=v.end(); it_v++)
+      *it_v = norm();
+    
+    return v;
+  }
