+namespace optimize {
+  Vector h(const Vector& v) {
+    double x = v(0);
+    return Vector_(2,cos(x),sin(x));
+  };
+  Matrix H(const Vector& v) {
+    double x = v(0);
+    return Matrix_(2,1,-sin(x),cos(x));
+  };
+}
+
+/* ************************************************************************* */
+NonlinearFactorGraph createReallyNonlinearFactorGraph()
+{
+  NonlinearFactorGraph fg;
