+
+/* ************************************************************************* */
+void Constructor::matlab_proxy_fragment(ofstream& ofs, const string& className) {
+  ofs << "      if nargin == " << args.size() << ", obj.self = " 
+      << matlab_wrapper_name(className) << "(";
+  bool first = true;
+  for(size_t i=0;i<args.size();i++) {
+    if (!first) ofs << ",";
+    ofs << "varargin{" << i+1 << "}";
+    first=false;
+  }
+  ofs << "); end" << endl;
+}
