+static Vector Q_p1 = Vector1::Ones();
+static Vector Q_p2 = Vector2::Ones();
+static Vector Q_p3 = Vector3::Ones();
+static Vector Q_se2 = Vector3::Ones();
+static Vector Q_se3 = Vector6::Ones();
